injectCSS:
/* ===== nord-plus : respiro, brilho e acabamento ===== */

/* titulos e leituras com brilho suave (nao afeta o canvas do terminal) */
h1, h2, h3, h3.title, #mod_clock_display, #main_shell_greeting {
    text-shadow: 0 0 0.55vh rgba(238, 220, 233, 0.22);
}

/* scanlines discretas de CRT */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 9999;
    pointer-events: none;
    background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.15) 0px, rgba(0, 0, 0, 0.15) 1px, transparent 1px, transparent 4px);
    opacity: 0.3;
}

/* titulos dos paineis um pouco maiores e mais espacados */
section > h3.title:first-child {
    font-size: 1.12vh;
    letter-spacing: 0.06vh;
}

/* painel central com profundidade */
section#main_shell {
    width: 64%;
    box-shadow: 0 0 2.2vh rgba(255, 121, 198, 0.10), inset 0 0 2.2vh rgba(21, 14, 22, 0.55);
}

/* colunas laterais levemente para dentro da tela */
section#mod_column_left { left: 0.2vh; }
section#mod_column_right { right: 0.2vh; }

/* mais espaco entre arquivos e teclado */
section#filesystem { margin-right: 1vw; }

/* tiles de arquivo arredondados com realce no hover */
div#fs_disp_container > * {
    border-radius: 0.5vh;
    transition: background-color 0.15s linear, box-shadow 0.15s linear;
}
div#fs_disp_container > *:hover {
    background-color: rgba(255, 121, 198, 0.12);
    box-shadow: 0 0 1vh rgba(255, 121, 198, 0.18);
}

/* abas do terminal */
ul#main_shell_tabs > li { transition: filter 0.15s linear; }
ul#main_shell_tabs > li:hover { filter: brightness(145%); }

/* teclas virtuais com cantos suaves */
div.keyboard_key {
    border-radius: 0.45vh;
    transition: filter 0.12s linear, box-shadow 0.12s linear;
}
div.keyboard_key:hover {
    filter: brightness(150%);
    box-shadow: 0 0 1vh rgba(255, 121, 198, 0.25);
}

/* barra de rolagem arredondada */
::-webkit-scrollbar-thumb { border-radius: 1vh; }
